from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        if all(x == 0 for x in nums):
            return 0

        n = len(nums)
        max_target = max(nums)
        mask = (1 << (max_target + 1)) - 1

        def can_make_zero(k: int) -> bool:
            dp = [1] * n

            for l, r, val in queries[:k]:
                shift = 1 << val
                for i in range(l, r + 1):
                    dp[i] |= dp[i] << val
                    dp[i] &= mask

            return all(dp[i] & (1 << nums[i]) for i in range(n))

        left, right = 1, len(queries)
        ans = -1

        while left <= right:
            mid = (left + right) // 2
            if can_make_zero(mid):
                ans = mid
                right = mid - 1
            else:
                left = mid + 1

        return ans
